/**
 * Unit tests for BasicSerializerFactory#buildIndexedListSerializer.
 */
public class BasicSerializerFactory_buildIndexedListSerializer_TriageGen1Test {

    private BasicSerializerFactory serializerFactory;
    private TypeFactory typeFactory;
    private JavaType elemType;
    private TypeSerializer vts;
    private JsonSerializer<Object> valueSerializer;

    @Before
    public void setUp() {
        // BasicSerializerFactory has a protected constructor requiring SerializerFactoryConfig.
        // Since SerializerFactoryConfig is usually managed by the factory, we can use a mock or a real empty config.
        SerializerFactoryConfig config = mock(SerializerFactoryConfig.class);

        // We use a concrete subclass or a mock of the abstract class to instantiate it.
        // However, since we are testing the logic of buildIndexedListSerializer which is public,
        // we can use a mock of the abstract class or a simple anonymous implementation.
        serializerFactory = new BasicSerializerFactory(config) {
            @Override
            public SerializerFactory withConfig(SerializerFactoryConfig config) {
                return this;
            }

            @Override
            protected Iterable<Serializers> customSerializers() {
                return null;
            }
        };

        typeFactory = TypeFactory.defaultInstance();
        elemType = typeFactory.constructType(String.class);
        vts = mock(TypeSerializer.class);
        valueSerializer = mock(JsonSerializer.class);
    }

    @Test
    public void testBuildIndexedListSerializer_Success() {
        // Act
        ContainerSerializer<?> result = serializerFactory.buildIndexedListSerializer(
                elemType, true, vts, valueSerializer);

        // Assert
        assertNotNull("The returned serializer should not be null", result);
        assertTrue("The returned serializer should be an instance of IndexedListSerializer",
                result instanceof IndexedListSerializer);
    }

    @Test
    public void testBuildIndexedListSerializer_WithFalseStaticTyping() {
        // Act
        ContainerSerializer<?> result = serializerFactory.buildIndexedListSerializer(
                elemType, false, vts, valueSerializer);

        // Assert
        assertNotNull("The returned serializer should not be null", result);
        assertTrue("The returned serializer should be an instance of IndexedListSerializer",
                result instanceof IndexedListSerializer);
    }

    @Test
    public void testBuildIndexedListSerializer_WithNullParameters() {
        // Testing robustness against nulls (though standard Jackson behavior expects non-null)
        // This ensures the constructor of IndexedListSerializer handles or receives them.

        ContainerSerializer<?> result = serializerFactory.buildIndexedListSerializer(
                null, true, null, null);

        assertNotNull("The returned serializer should not be null even if params are null", result);
        assertTrue(result instanceof IndexedListSerializer);
    }
}
